def hlw(t):
    m = re.fullmatch(r'(.*?)<b class="k">(.*?)</b>(.*)', t)
    if m: return m.group(1) + '<span class="hl">' + m.group(2) + '</span>' + m.group(3)
    t2 = t.rstrip('（，：'); return '<span class="hl">' + t2 + '</span>' + t[len(t2):]
